import pytest
from candidate import strange_sort_list

@pytest.mark.parametrize("input_list, expected", [
    ([], []),
    ([1], [1]),
    ([1, 2, 3, 4], [1, 4, 2, 3]),
    ([1, 2, 3, 4], [1, 4, 2, 3]),
    ([5, 5, 5, 5], [5, 5, 5, 5]),
])
def test_strange_sort_list_empty_and_single_element(input_list, expected):
    assert strange_sort_list(input_list) == expected

